- (instancetype)initWithJSONDictionary:(NSDictionary *)dict
{
    if (self = [super init]) {
        if (![dict[@"active"] isKindOfClass:NSNumber.class]) return nil;
        if (!dict[@"anything"]) return nil;
        if (![dict[@"byName"] isKindOfClass:NSDictionary.class]) return nil;
        if (dict[@"code"] && [dict[@"code"] rangeOfString:@"^[A-Z]\\d+\\\\$" options:NSRegularExpressionSearch].location == NSNotFound) return nil;
        if (dict[@"code"] && [dict[@"code"] lengthOfBytesUsingEncoding:NSUTF32StringEncoding] / 4 < 2) return nil;
        if ([dict[@"code"] lengthOfBytesUsingEncoding:NSUTF32StringEncoding] / 4 > 8) return nil;
        if (![dict[@"code"] isKindOfClass:NSString.class]) return nil;
        if (dict[@"count"] && [dict[@"count"] doubleValue] < 1) return nil;
        if (dict[@"count"] && [dict[@"count"] doubleValue] > 1e+21) return nil;
        if (![dict[@"count"] isKindOfClass:NSNumber.class]) return nil;
        if ([dict[@"count"] doubleValue] != [dict[@"count"] longLongValue]) return nil;
        if (![dict[@"counts"] isKindOfClass:NSDictionary.class]) return nil;
        for (id value in [dict[@"counts"] allValues]) if (![value isKindOfClass:NSNumber.class]) return nil;
        if (dict[@"created"] && [dict[@"created"] rangeOfString:@"^[0-9]{4}-[0-9]{2}-[0-9]{2}T" options:NSRegularExpressionSearch].location == NSNotFound) return nil;
        if (![dict[@"created"] isKindOfClass:NSString.class]) return nil;
        if (![dict[@"description"] isKindOfClass:NSString.class]) return nil;
        if (![dict[@"flags"] isKindOfClass:NSDictionary.class]) return nil;
        for (id value in [dict[@"flags"] allValues]) if (![value isKindOfClass:NSNumber.class]) return nil;
        if (dict[@"id"] && ![[NSUUID alloc] initWithUUIDString:dict[@"id"]]) return nil;
        if (![dict[@"id"] isKindOfClass:NSString.class]) return nil;
        if (!dict[@"isOn"]) return nil;
        if (![dict[@"kind"] isKindOfClass:NSString.class]) return nil;
        if (!dict[@"maybeInt"]) return nil;
        if (!dict[@"maybePoint"]) return nil;
        if (!dict[@"nothing"]) return nil;
        if (![dict[@"point"] isKindOfClass:NSDictionary.class]) return nil;
        if (![dict[@"points"] isKindOfClass:NSArray.class]) return nil;
        if (dict[@"ratio"] && [dict[@"ratio"] doubleValue] < -0.5) return nil;
        if (dict[@"tags"] && [(NSArray *)dict[@"tags"] count] < 1) return nil;
        if ([(NSArray *)dict[@"tags"] count] > 10) return nil;
        if (![dict[@"tags"] isKindOfClass:NSArray.class]) return nil;
        [self setValuesForKeysWithDictionary:dict];
        _byName = map(_byName, λ(id x, [QTPoint fromJSONDictionary:x]));
        _empty = [QTEmpty fromJSONDictionary:(id)_empty];
        if (!_empty && dict[@"empty"] && ![dict[@"empty"] isKindOfClass:NSNull.class]) return nil;
        _kind = [QTKind withValue:(id)_kind];
        _kinds = map(_kinds, λ(id x, [QTKind withValue:x]));
        _maybeKind = [QTKind withValue:(id)_maybeKind];
        if (_maybeKind == nil && dict[@"maybeKind"] && ![dict[@"maybeKind"] isKindOfClass:NSNull.class]) return nil;
        _maybePoint = [QTPoint fromJSONDictionary:(id)_maybePoint];
        if (!_maybePoint && dict[@"maybePoint"] && ![dict[@"maybePoint"] isKindOfClass:NSNull.class]) return nil;
        _nested = map(_nested, λ(id x, map(x, λ(id x, [QTPoint fromJSONDictionary:x]))));
        _point = [QTPoint fromJSONDictionary:(id)_point];
        if (!_point && dict[@"point"] && ![dict[@"point"] isKindOfClass:NSNull.class]) return nil;
        _points = map(_points, λ(id x, [QTPoint fromJSONDictionary:x]));
    }
    return self;
}

